<script setup lang="ts">
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { ElButton } from 'element-plus'
import { ArrowRight, Plus, FileSignature, RotateCcw, PackageCheck, Store, MapPin, ArrowUpRight, ClipboardCheck } from 'lucide-vue-next'
import { useProfileStore } from '@/stores/profile'
import { useCommerceStore, money, STATUS_LABEL } from '@/stores/commerce'
import { orderStages, STAGE_LABEL } from '@/utils/orderStages'
const router = useRouter(), profile = useProfileStore(), c = useCommerceStore()
const today = new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' })
const greeting = new Date().getHours() < 12 ? '上午好' : new Date().getHours() < 18 ? '下午好' : '晚上好'
const refunds = computed(() => c.data.refunds.filter(r => r.status === 'pending'))
const contracts = computed(() => c.data.orders.filter(o => o.status === 'pending_contract' && !c.activeRefund(o.id) && o.contractState !== 'waiting'))
const delivery = computed(() => c.data.orders.filter(o => o.status === 'in_service' && !c.activeRefund(o.id)))
const tasks = computed(() => refunds.value.length + contracts.value.length + delivery.value.length)
const onSale = computed(() => c.data.services.filter(s => Object.values(s.listings).some(x => x.status === 'on_sale')).length)
const score = computed(() => { const reviews = c.data.reviews.filter(r => r.direction === 'to_supplier'); return reviews.length ? (reviews.reduce((sum,r) => sum+r.score,0)/reviews.length).toFixed(1) : '—' })
const queue = computed(() => [
  ...refunds.value.map(r => ({ id:r.orderId, title:c.data.orders.find(o=>o.id===r.orderId)?.serviceName || '售后订单', label:'退款待处理', detail:`客户申请 ${money(r.requested)}`, action:'处理退款', tone:'urgent', path:`/order/${r.orderId}?tab=bill&refund=${r.id}` })),
  ...contracts.value.map(o => ({ id:o.id, title:o.serviceName, label:'待签约', detail:o.contractState === 'rejected' ? '合同已驳回，请修改后重新上传' : '请上传服务合同，等待客户确认', action:'上传合同', tone:'contract', path:`/order/${o.id}?tab=contract` })),
  ...delivery.value.map(o => { const phase = orderStages(o).find(s=>s.status!=='accepted'); return { id:o.id, title:o.serviceName, label:phase ? STAGE_LABEL[phase.status] : STATUS_LABEL[o.status], detail:phase?.name || '准备交付成果', action:'去履约', tone:'delivery', path:`/order/${o.id}?tab=delivery` } }),
].slice(0,5))
const setup = computed(() => [
  { title:'开通钱包', desc:'开通交易能力', path:'/wallet', show:!c.data.walletOpen },
  { title:'完善店铺资料', desc:'让客户了解你的服务', path:'/shop/info', show:!c.data.shop.name || !c.data.shop.intro },
  { title:'发布第一项服务', desc:'提交园区审核后开始接单', path:'/service/new', show:!c.data.services.length },
].filter(x=>x.show))
function parkService(id: string) { return c.data.services.filter(s => s.listings[id]?.status === 'on_sale').length }
</script>
<template>
  <div class="biz-page workbench">
    <header class="workbench-head"><div><p>{{ today }}<span>工作台</span></p><h1>{{ greeting }}，{{ profile.name }}</h1><div class="workbench-subtitle">{{ c.data.shop.name || '我的店铺' }} · 今天从待办开始。</div></div><ElButton type="primary" @click="router.push('/service/new')"><Plus :size="16" /> 发布服务</ElButton></header>
    <section class="work-focus">
      <div class="focus-intro"><span>需要你推进</span><div><strong>{{ tasks }}</strong><b>项待办</b></div><p>{{ tasks ? '及时响应客户，让每一笔服务稳步向前。' : '待办已处理，继续拓展你的园区业务。' }}</p><button @click="router.push(queue[0]?.path || '/service')">{{ tasks ? '开始处理' : '管理服务' }} <ArrowRight :size="16" /></button></div>
      <div class="focus-tasks"><button :class="{ urgent: refunds.length }" @click="router.push('/aftersale')"><span class="task-label"><RotateCcw :size="19" /> 退款待处理</span><strong>{{ refunds.length }}</strong><small>优先响应客户申请 <ArrowUpRight :size="14" /></small></button><button @click="router.push('/order')"><span class="task-label"><FileSignature :size="19" /> 待上传合同</span><strong>{{ contracts.length }}</strong><small>确认合作，启动服务 <ArrowUpRight :size="14" /></small></button><button @click="router.push('/order')"><span class="task-label"><PackageCheck :size="19" /> 待推进交付</span><strong>{{ delivery.length }}</strong><small>提交成果或修改交付 <ArrowUpRight :size="14" /></small></button></div>
    </section>
    <div class="work-layout">
      <section class="work-panel work-queue"><header><div><h2>待办订单</h2><p>先处理退款，再推进签约与交付</p></div><ElButton text @click="router.push('/order')">全部订单 <ArrowRight :size="14" /></ElButton></header><div v-if="!queue.length" class="queue-empty"><ClipboardCheck :size="32" /><h3>当前没有待办订单</h3><p>新订单和售后申请会出现在这里。</p></div><article v-for="item in queue" :key="item.id" class="queue-row"><div class="queue-status" :class="item.tone">{{ item.label }}</div><div class="queue-copy"><h3>{{ item.title }}</h3><p>{{ item.detail }}</p><small>{{ item.id }}</small></div><ElButton :type="item.tone === 'urgent' ? 'danger' : 'primary'" text @click="router.push(item.path)">{{ item.action }}</ElButton></article></section>
      <aside class="work-side"><section class="work-panel overview-panel"><header><div><h2>经营概览</h2><p>当前主体 · 累计数据</p></div><Store :size="19" /></header><div class="overview-grid"><button @click="router.push('/service')"><span>已上架服务</span><strong>{{ onSale }}<small>项</small></strong></button><button @click="router.push('/order')"><span>累计订单</span><strong>{{ c.data.orders.length }}<small>笔</small></strong></button><button @click="router.push('/review')"><span>店铺评分</span><strong>{{ score }}<small>/ 5</small></strong></button><button @click="router.push('/park')"><span>已加入园区</span><strong>{{ c.joinedParks.length }}<small>个</small></strong></button></div><button class="revenue" @click="router.push('/order')"><span>累计实收 <small>支付减已退款</small></span><strong>{{ money(c.data.orders.reduce((n,o)=>n+o.paid-o.refunded,0)) }}</strong></button></section>
      <section class="work-panel park-brief"><header><h2>园区业务</h2><button @click="router.push('/park')">管理 <ArrowUpRight :size="13" /></button></header><button v-for="park in c.joinedParks.slice(0,3)" :key="park.id" class="park-brief-row" @click="router.push({path:'/service',query:{park:park.id}})"><MapPin :size="16" /><span><strong>{{ park.name }}</strong><small>{{ parkService(park.id) }} 项服务已上架</small></span><ArrowRight :size="14" /></button><p v-if="!c.joinedParks.length" class="muted">加入园区后即可在这里查看业务。</p></section></aside>
    </div>
    <section v-if="setup.length" class="work-setup"><h2>完善经营准备</h2><button v-for="item in setup" :key="item.title" @click="router.push(item.path)"><strong>{{ item.title }}</strong><span>{{ item.desc }}</span><ArrowRight :size="15" /></button></section>
    <nav class="quick-links"><span>常用入口</span><button @click="router.push('/shop/info')">店铺资料</button><button @click="router.push('/shop/cases')">案例管理</button><button @click="router.push('/wallet')">我的钱包</button><button @click="router.push('/invoice/record')">发票管理</button></nav>
  </div>
</template>
<style scoped>
